-- C04 PREFLIGHT — READ ONLY. Generated by build-and-verify.py; do not edit by hand.
-- Run each query on its own (select the query text, then Run). Nothing here writes.

-- QUERY A — readiness. Every row with an expected value must show ok = true; last row SUMMARY must say "0 failed".
with patches(n, old_text, new_text) as (values
  (1, $a$or exists(select 1 from jsonb_object_keys(p_values) k where k<>all(fields)) then$a$, $a$or exists(select 1 from jsonb_object_keys(p_values) k where k<>all(fields) and k<>'discount_mode') then$a$),
  (2, $a$values_row:=jsonb_populate_record(null::public.promos,p_values-array['suggest','min_subtotal']);$a$, $a$values_row:=jsonb_populate_record(null::public.promos,p_values-array['suggest','min_subtotal','discount_mode']);$a$),
  (3, $a$select coalesce(array_agg(distinct id order by id),'{}') into item_ids from unnest(p_item_ids) id;$a$, $a$select coalesce(array_agg(distinct id order by id),'{}') into item_ids from unnest(p_item_ids) id;
 if p_values ? 'discount_mode' and (jsonb_typeof(p_values->'discount_mode')<>'string' or p_values->>'discount_mode' not in('per_unit','package_total')) then
  raise exception 'Cara hitung diskon promo tidak valid';
 end if;
 if coalesce(p_values->>'discount_mode',existing.rule->>'discount_mode','per_unit')='package_total'
  and (values_row.discount_type is distinct from 'nominal' or values_row.min_qty is null or cardinality(item_ids)<>1) then
  raise exception 'Total per paket memerlukan diskon nominal, min. qty, dan tepat satu barang target';
 end if;$a$),
  (4, $a$if min_subtotal is not null then new_rule:=new_rule||jsonb_build_object('min_subtotal',min_subtotal);end if;$a$, $a$if min_subtotal is not null then new_rule:=new_rule||jsonb_build_object('min_subtotal',min_subtotal);end if;
 if p_values ? 'discount_mode' then
  if p_values->>'discount_mode'='per_unit' then new_rule:=new_rule-'discount_mode';
  else new_rule:=new_rule||jsonb_build_object('discount_mode','package_total');end if;
 end if;$a$)
), anchors as (
  select n, old_text, new_text, pg_get_functiondef(to_regprocedure('public.edit_promo(uuid,text,jsonb,uuid[])')) as def from patches
), checks(check_name, expected, actual) as (
  select 'info: server version', null, current_setting('server_version')
  union all select 'info: database', null, current_database()
  union all select 'prerequisite: public.edit_promo(uuid,text,jsonb,uuid[]) exists', 'true', (to_regprocedure('public.edit_promo(uuid,text,jsonb,uuid[])') is not null)::text
  union all select 'editor security definer', 'true', (select prosecdef::text from pg_proc where oid = to_regprocedure('public.edit_promo(uuid,text,jsonb,uuid[])'))
  union all select 'editor search_path empty', 'true', (select coalesce(proconfig @> array['search_path=""']::text[], false)::text from pg_proc where oid = to_regprocedure('public.edit_promo(uuid,text,jsonb,uuid[])'))
  union all select 'editor grant: anon', 'false', has_function_privilege('anon', 'public.edit_promo(uuid,text,jsonb,uuid[])', 'EXECUTE')::text
  union all select 'editor grant: service_role', 'false', has_function_privilege('service_role', 'public.edit_promo(uuid,text,jsonb,uuid[])', 'EXECUTE')::text
  union all select 'editor owned by the role running this (needed for CREATE OR REPLACE)', 'true', (select pg_get_userbyid(proowner) = current_user from pg_proc where oid = to_regprocedure('public.edit_promo(uuid,text,jsonb,uuid[])'))::text
  union all select 'editor grant: authenticated', 'true', has_function_privilege('authenticated', 'public.edit_promo(uuid,text,jsonb,uuid[])', 'EXECUTE')::text
  union all select 'prerequisite: promo_configuration_guard triggers', '2', (select count(*) from pg_trigger where tgname = 'promo_configuration_guard' and tgrelid in ('public.promos'::regclass, 'public.promo_items'::regclass))::text
  union all select 'info: promos total', null, (select count(*) from public.promos)::text
  union all select 'info: active promos', null, (select count(*) from public.promos where is_active)::text
  union all select 'not yet applied: constraint promos_discount_mode_valid', '0', (select count(*) from pg_constraint where conname = 'promos_discount_mode_valid')::text
  union all select 'not yet applied: public.assert_active_package_promo_target() absent', 'true', (to_regprocedure('public.assert_active_package_promo_target()') is null)::text
  union all select 'not yet applied: C04 triggers', '0', (select count(*) from pg_trigger where tgname in ('promo_package_target_header_guard', 'promo_package_target_items_guard'))::text
  union all select 'fingerprint (same as repository): public.edit_promo(uuid,text,jsonb,uuid[])', 'f4a53d51521eecb175dd646f66ee82e9', (select md5(prosrc) from pg_proc where oid = to_regprocedure('public.edit_promo(uuid,text,jsonb,uuid[])'))
  union all select 'anchor ' || n || ' found exactly once', '1', ((length(def) - length(replace(def, old_text, ''))) / length(old_text))::text from anchors
  union all select 'data: promos already storing discount_mode (app flag is off, expect none)', '0', (select count(*) from public.promos where rule ? 'discount_mode')::text
)
select check_name, expected, actual,
  case when expected is null then null else actual is not distinct from expected end as ok
from checks
union all
select 'SUMMARY', '0 failed',
  count(*) filter (where expected is not null and actual is distinct from expected) || ' failed',
  count(*) filter (where expected is not null and actual is distinct from expected) = 0
from checks;

-- QUERY B — migration history. Expect NO row 20261026002100. Note the newest rows (C04 is older than several
-- applied versions, so it is applied out of order on purpose). If the table does not exist, tell the developer.
select version, name from supabase_migrations.schema_migrations
where version >= '20261025' or version = '20261026002100' order by version desc;

-- QUERY C — keep a copy of the editor definition before C04 (export as CSV next to the backup note).
-- Only needed for the fallback rollback path.
select 'public.edit_promo(uuid,text,jsonb,uuid[])' as sig, pg_get_functiondef(to_regprocedure('public.edit_promo(uuid,text,jsonb,uuid[])')) as definition_before_c04;
